<template>
<section class="china-calendar" :class="{'calendar-dark':dark}" aria-labelledby="china-calendar-title">
  <header class="calendar-heading"><div><h2 id="china-calendar-title">中国节假日日历</h2><p>公历与农历 · 放假调休 · 中国标准时间（UTC+8）</p></div><button type="button" @click="expanded=!expanded" :aria-expanded="expanded">{{expanded?'收起':'展开'}}</button></header>
  <template v-if="expanded">
    <div class="calendar-navigation"><button type="button" aria-label="上个月" @click="move(-1)">‹</button><label class="sr-only" for="calendar-year">年份</label><select id="calendar-year" v-model.number="year"><option v-for="y in years" :key="y" :value="y">{{y}}年</option></select><label class="sr-only" for="calendar-month">月份</label><select id="calendar-month" v-model.number="month"><option v-for="m in 12" :key="m" :value="m">{{m}}月</option></select><button type="button" aria-label="下个月" @click="move(1)">›</button><button type="button" @click="goToday">回到今天</button><span class="calendar-legend"><i class="legend-off"></i>放假 <i class="legend-work"></i>调休上班 <i class="legend-weekend"></i>普通周末</span></div>
    <p v-if="!schedule" class="calendar-notice" role="status">{{year}} 年官方放假调休安排尚未收录，暂仅展示日期、农历及普通周末，不推测放假日期。</p>
    <div class="calendar-layout"><div class="calendar-month-view"><div class="calendar-weekdays"><span v-for="w in weekdays" :key="w">{{w}}</span></div><div class="calendar-days"><button v-for="day in days" :key="day.iso" type="button" class="calendar-day" :class="[day.status.type,{'other-month':!day.inMonth,today:day.iso===today,selected:day.iso===selected}]" :aria-label="`${day.iso} 农历${day.lunar.label} ${day.status.label}`" :aria-pressed="day.iso===selected" :aria-current="day.iso===today?'date':undefined" @click="selectDay(day)"><span class="calendar-number">{{day.day}}<b v-if="day.status.badge">{{day.status.badge}}</b></span><span class="calendar-lunar">{{day.status.name||day.lunar.short}}</span></button></div></div>
    <aside class="calendar-details"><div class="selected-date"><strong>{{selected}}</strong><p>农历 {{selectedLunar.label}}</p><span :class="['day-status',selectedStatus.type]">{{selectedStatus.label}}</span></div><h3>{{year}} 年放假安排</h3><ul v-if="schedule" class="calendar-holidays"><li v-for="h in schedule.holidays" :key="h.name"><button type="button" @click="jump(h.start)"><strong>{{h.name}}</strong><span>{{range(h)}} · {{duration(h)}} 天</span></button></li></ul><p v-else class="calendar-no-schedule">该年份暂无已收录的官方安排。</p></aside></div>
    <footer>已收录：2026 年。红色「休」为官方放假调休日期，橙色「班」为调休上班；普通周末单独标示。实际作息以单位安排为准。<a v-if="schedule" :href="schedule.source" target="_blank" rel="noopener noreferrer">{{schedule.document}} · 查看官方通知 ↗</a></footer>
  </template>
</section>
</template>
<script>
import {holidaySchedules} from '../data/china-holidays.mjs';
import {chinaDateISO,lunarForISO,dayStatus,monthDays} from '../utils/china-calendar.mjs';
export default {
 name:'ChinaCalendar',props:{dark:Boolean},
 data(){const today=chinaDateISO();return {expanded:true,today,selected:today,year:Number(today.slice(0,4)),month:Number(today.slice(5,7)),weekdays:['一','二','三','四','五','六','日'],timer:null};},
 computed:{years(){return Array.from(new Set([2024,2025,2026,2027,2028,2029,2030,this.year])).sort((a,b)=>a-b);},schedule(){return holidaySchedules[this.year];},days(){return monthDays(this.year,this.month);},selectedLunar(){return lunarForISO(this.selected);},selectedStatus(){return dayStatus(this.selected);}},
 watch:{year(){this.syncSelected();},month(){this.syncSelected();}},
 mounted(){this.timer=setInterval(()=>{this.today=chinaDateISO();},60000);},beforeUnmount(){clearInterval(this.timer);},
 methods:{syncSelected(){const prefix=`${this.year}-${String(this.month).padStart(2,'0')}`;if(!this.selected.startsWith(prefix))this.selected=prefix+'-01';},move(delta){const d=new Date(Date.UTC(this.year,this.month-1+delta,1));this.year=d.getUTCFullYear();this.month=d.getUTCMonth()+1;this.selected=`${this.year}-${String(this.month).padStart(2,'0')}-01`;},jump(iso){this.year=Number(iso.slice(0,4));this.month=Number(iso.slice(5,7));this.selected=iso;},goToday(){this.today=chinaDateISO();this.jump(this.today);},selectDay(day){this.jump(day.iso);},range(h){return `${h.start.slice(5).replace('-','/')}—${h.end.slice(5).replace('-','/')}`;},duration(h){return Math.round((Date.parse(h.end)-Date.parse(h.start))/86400000)+1;}}
};
</script>
