h;gap:8px;padding:10px;min-width:0;min-height:75px;text-align:left;background:var(--cal-cell)}.calendar-number{display:flex;justify-content:space-between;gap:4px;align-items:center;font-size:18px;font-variant-numeric:tabular-nums}.calendar-number b{font-size:10px;font-weight:500;padding:1px 4px;border-radius:4px}.calendar-day.holiday{background:rgba(223,109,102,.08);color:#cc625e}.holiday .calendar-number b{background:#df6d66;color:white}.work .calendar-number b{background:#bf8b37;color:white}.calendar-day.weekend .calendar-number{color:var(--cal-muted)}.calendar-lunar{font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--cal-muted)}.holiday .calendar-lunar{color:#cc625e}.calendar-day.other-month{opacity:.38}.china-calendar .calendar-day.today{border-color:#43898d}.china-calendar .calendar-day.selected{outline:2px solid #43898d;outline-offset:-2px}.calendar-details{border-left:1px solid var(--cal-line);padding-left:20px;min-width:0}.selected-date{padding:12px;border-radius:10px;background:var(--cal-cell)}.selected-date>strong{font-size:18px}.selected-date p{font-size:12px;color:var(--cal-muted);line-height:1.7}.day-status{font-size:11px;padding:4px 6px;border-radius:4px;background:var(--cal-cell);color:var(--cal-muted)}.day-status.holiday{color:#cc625e;background:rgba(223,109,102,.1)}.day-status.work{color:#bf8b37;background:rgba(191,139,55,.1)}.calendar-details h3{font-size:13px;margin:18px 0 8px}.calendar-holidays{list-style:none;padding:0;margin:0}.calendar-holidays li button{display:flex;justify-content:space-between;gap:8px;align-items:center;width:100%;padding:10px 0;border:0;border-bottom:1px solid var(--cal-line);border-radius:0;font-size:11px;text-align:left}.calendar-holidays span,.calendar-no-schedule{font-size:11px;color:var(--cal-muted);line-height:1.7}footer{font-size:10px;color:var(--cal-muted);line-height:1.8;margin-top:16px}footer a{color:inherit;margin-left:6px}.sr-only{position:absolute;width:1px;height:1px;overflow: